// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 val1, uint256 val2) internal {
        vm.assume(val1 != val2);
        try c.Initialized() {} catch { return; }
        try c.SetMinSum(val1) {} catch { return; }
        try c.SetMinSum(val2) {} catch { return; }
        uint256 minSum;
        try c.MinSum() returns (uint256 __r) { minSum = __r; } catch { return; }
        assertTrue(minSum == val1);
    }

    function testFuzz_run(uint256 val1, uint256 val2) public {
        _run(val1, val2);
    }

    receive() external payable {}
}
